mapper.update:
UPDATE solutions
SET description = #{description}
WHERE id = #{id}
  AND grade IS NULL

UPDATE solutions
SET grade = #{grade},
    teacher_comment = #{teacherComment},
    graded_at = #{gradedAt}
WHERE id = #{id}

mapper.select:
SELECT id, task_id, description, grade, teacher_comment, graded_at
FROM solutions
WHERE id = #{solutionId}

SELECT id, task_id, description, grade, teacher_comment, graded_at
FROM solutions
WHERE task_id = #{taskId}

SELECT EXISTS(
    SELECT 1
    FROM solution_files
    WHERE solution_id = #{solutionId} AND file_id = #{fileId}
)
